+package com.finboost.bank.statement.parser.service.document.extraction.local;
+
+import com.finboost.bank.statement.parser.representation.document.extraction.DocumentExtractionResult;
+import com.finboost.bank.statement.parser.representation.document.extraction.Page;
+import com.finboost.bank.statement.parser.representation.document.extraction.Table;
+import com.finboost.bank.statement.parser.representation.document.extraction.TableCell;
+import com.finboost.bank.statement.parser.representation.document.extraction.Word;
+import org.apache.pdfbox.Loader;
+import org.apache.pdfbox.pdmodel.PDDocument;
+import org.apache.pdfbox.pdmodel.PDPage;
+import org.apache.pdfbox.pdmodel.common.PDRectangle;
+import org.apache.pdfbox.text.PDFTextStripper;
+import org.apache.pdfbox.text.TextPosition;
+import org.springframework.stereotype.Service;
+
+import java.io.File;
+import java.io.IOException;
+import java.util.ArrayList;
+import java.util.Arrays;
+import java.util.Comparator;
+import java.util.LinkedHashMap;
+import java.util.List;
+import java.util.Locale;
+import java.util.Map;
+import java.util.Optional;
+import java.util.regex.Pattern;
+import java.util.stream.Collectors;
+
+@Service
+public class NativeDocumentTableExtractor {
+    private static final float POINTS_PER_INCH = 72.0f;
+    private static final Pattern DATE = Pattern.compile("^(?:\\d{1,2}[-/.]\\d{1,2}[-/.](?:\\d{2}|\\d{4})|\\d{1,2}[- ](?:jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*[- ,]\\d{2,4})$", Pattern.CASE_INSENSITIVE);
+
+    public Optional<DocumentExtractionResult> extract(File pdf, NativeTablePolicy policy) throws IOException {
+        try (PDDocument document = Loader.loadPDF(pdf)) {
+            Map<Integer, Page> pages = new LinkedHashMap<>();
+            List<PageLines> pageLines = new ArrayList<>();
+            int wordIndex = 1;
+
+            for (int pageIndex = 0; pageIndex < document.getNumberOfPages(); pageIndex++) {
+                PDPage pdPage = document.getPage(pageIndex);
+                PositionStripper stripper = new PositionStripper(pageIndex + 1);
+                stripper.setStartPage(pageIndex + 1);
+                stripper.setEndPage(pageIndex + 1);
+                String content = stripper.getText(document);
+                List<Word> words = stripper.toWords();
+                for (Word word : words) {
+                    word.setPageIndex(pageIndex + 1);
+                    word.setWordIndex(wordIndex++);
+                }
+
+                PDRectangle box = pdPage.getCropBox();
+                Page page = new Page();
+                page.setPageNumber(pageIndex + 1);
+                page.setWidth((double) box.getWidth() / POINTS_PER_INCH);
+                page.setHeight((double) box.getHeight() / POINTS_PER_INCH);
+                page.setWords(words);
+                page.setContent(content);
+                page.setTables(new LinkedHashMap<>());
+                pages.put(pageIndex + 1, page);
+                pageLines.add(new PageLines(page, groupLines(words)));
+            }
+
+            Header globalHeader = pageLines.stream()
+                    .flatMap(page -> page.lines().stream())
+                    .map(this::headerFor)
+                    .filter(Optional::isPresent)
+                    .map(Optional::get)
+                    .findFirst()
+                    .orElse(null);
+            if (globalHeader == null) {
+                return Optional.empty();
+            }
+
+            int transactionRows = 0;
+            for (PageLines page : pageLines) {
+                Header header = page.lines().stream().map(this::headerFor).filter(Optional::isPresent)
+                        .map(Optional::get).findFirst().orElse(globalHeader);
+                Table table = createTable(page, header, policy);
+                if (table != null) {
+                    page.page().getTables().put(0, table);
+                    transactionRows += Math.max(0, table.getTotalRows() - 1);
+                }
+            }
+            if (transactionRows < 2) {
+                return Optional.empty();
+            }
+
+            DocumentExtractionResult result = new DocumentExtractionResult();
+            result.setPages(pages);
+            result.setNoOfPages(pages.size());
+            return Optional.of(result);
+        }
+    }
+
+    private Table createTable(PageLines pageLines, Header header, NativeTablePolicy policy) {
+        List<List<Word>> lines = pageLines.lines();
+        int headerIndex = lines.indexOf(header.words());
+        if (headerIndex < 0) {
+            headerIndex = firstTransactionLine(lines);
+        }
+        if (headerIndex < 0) {
+            return null;
+        }
+
+        List<List<Word>> rows = new ArrayList<>();
+        if (lines.indexOf(header.words()) >= 0) {
+            rows.add(header.words());
+        } else {
+            rows.add(new ArrayList<>());
+        }
+        List<Word> current = null;
+        for (int i = headerIndex + (lines.indexOf(header.words()) >= 0 ? 1 : 0); i < lines.size(); i++) {
+            List<Word> line = lines.get(i);
+            if (startsWithDate(line)) {
+                current = new ArrayList<>(line);
+                rows.add(current);
+            } else if (current != null && isContinuation(line, header, policy)) {
+                current.addAll(line);
+            } else if (current != null && looksLikeFooter(line)) {
+                break;
+            }
+        }
+        if (rows.size() < 3) {
+            return null;
+        }
+
+        List<Float> anchors = header.anchors();
+        List<Float> boundaries = boundaries(anchors, (float) pageLines.page().getWidth().doubleValue());
+        Map<Integer, Map<Integer, TableCell>> cells = new LinkedHashMap<>();
+        for (int rowIndex = 0; rowIndex < rows.size(); rowIndex++) {
+            List<Word> rowWords = rows.get(rowIndex);
+            Map<Integer, TableCell> row = new LinkedHashMap<>();
+            float top = rowWords.stream().map(Word::getY1).min(Float::compareTo).orElse(0f);
+            float bottom = rowWords.stream().map(Word::getY3).max(Float::compareTo).orElse(top + 0.1f);
+            for (int col = 0; col < boundaries.size() - 1; col++) {
+                float left = boundaries.get(col);
+                float right = boundaries.get(col + 1);
+                List<Word> cellWords = rowWords.stream()
+                        .filter(word -> centerX(word) >= left && centerX(word) < right)
+                        .sorted(Comparator.comparing(Word::getActualY1).thenComparing(Word::getActualX1))
+                        .collect(Collectors.toList());
+                row.put(col, cell(rowIndex, col, left, right, top, bottom, cellWords));
+            }
+            cells.put(rowIndex, row);
+        }
+
+        Table table = new Table();
+        table.setPageNumber(pageLines.page().getPageNumber());
+        table.setX1(boundaries.get(0));
+        table.setX2(boundaries.get(boundaries.size() - 1));
+        table.setX3(table.getX2());
+        table.setX4(table.getX1());
+        table.setY1(cells.get(0).values().stream().map(TableCell::getY1).min(Float::compareTo).orElse(0f));
+        table.setY2(table.getY1());
+        table.setY3(cells.get(cells.size() - 1).values().stream().map(TableCell::getY3).max(Float::compareTo).orElse(table.getY1()));
+        table.setY4(table.getY3());
+        table.setCells(cells);
+        table.setTotalRows(cells.size());
+        table.setTotalColumns(anchors.size());
+        table.setColType(new ArrayList<>());
+        table.setTxnColType(new ArrayList<>());
+        table.setColumnBoundaries(boundaries);
+        return table;
+    }
+
+    private Optional<Header> headerFor(List<Word> words) {
+        List<Anchor> anchors = new ArrayList<>();
+        for (Word word : words) {
+            String value = word.getContent().toLowerCase(Locale.ROOT).replaceAll("[^a-z/]", "");
+            String type = null;
+            if (value.contains("date") || value.equals("txn") || value.startsWith("tran")) type = "date";
+            if (value.startsWith("value")) type = "value-date";
+            if (value.contains("narr") || value.contains("particular") || value.contains("description") || value.equals("details")) type = "description";
+            if (value.contains("cheque") || value.startsWith("chq") || value.equals("reference") || value.equals("ref")) type = "reference";
+            if (value.contains("withdraw") || value.equals("debit") || value.equals("dr")) type = "debit";
+            if (value.contains("deposit") || value.equals("credit") || value.equals("cr")) type = "credit";
+            if (value.contains("amount")) type = "amount";
+            if (value.contains("balance") || value.equals("bal")) type = "balance";
+            if (value.equals("dr/cr") || value.equals("cr/dr") || value.equals("type")) type = "type";
+            if (type != null && anchors.stream().noneMatch(anchor -> anchor.type().equals(type))) {
+                anchors.add(new Anchor(type, word.getX1()));
+            }
+        }
+        boolean date = anchors.stream().anyMatch(anchor -> anchor.type().equals("date"));
+        boolean balance = anchors.stream().anyMatch(anchor -> anchor.type().equals("balance"));
+        boolean amount = anchors.stream().anyMatch(anchor -> Arrays.asList("debit", "credit", "amount").contains(anchor.type()));
+        if (!date || !balance || !amount || anchors.size() < 3) {
+            return Optional.empty();
+        }
+        List<Float> positions = anchors.stream().sorted(Comparator.comparing(Anchor::x)).map(Anchor::x).collect(Collectors.toList());
+        return Optional.of(new Header(words, positions));
+    }
+
+    private List<List<Word>> groupLines(List<Word> words) {
+        List<List<Word>> lines = new ArrayList<>();
+        for (Word word : words.stream().sorted(Comparator.comparing(Word::getY1).thenComparing(Word::getX1)).toList()) {
+            List<Word> line = lines.stream()
+                    .filter(candidate -> Math.abs(candidate.get(0).getY1() - word.getY1()) <= Math.max(0.025f, word.getHeight() * 0.45f))
+                    .findFirst().orElse(null);
+            if (line == null) {
+                line = new ArrayList<>();
+                lines.add(line);
+            }
+            line.add(word);
+        }
+        lines.forEach(line -> line.sort(Comparator.comparing(Word::getX1)));
+        return lines;
+    }
+
+    private int firstTransactionLine(List<List<Word>> lines) {
+        for (int i = 0; i < lines.size(); i++) {
+            if (startsWithDate(lines.get(i))) return i;
+        }
+        return -1;
+    }
+
+    private boolean startsWithDate(List<Word> line) {
+        for (int i = 0; i < Math.min(3, line.size()); i++) {
+            String one = line.get(i).getContent().replaceAll("[,;]$", "");
+            String two = i + 1 < line.size() ? one + " " + line.get(i + 1).getContent() : one;
+            String three = i + 2 < line.size() ? two + " " + line.get(i + 2).getContent() : two;
+            if (DATE.matcher(one).matches() || DATE.matcher(two).matches() || DATE.matcher(three).matches()) return true;
+        }
+        return false;
+    }
+
+    private boolean isContinuation(List<Word> line, Header header, NativeTablePolicy policy) {
+        if (line.isEmpty() || looksLikeFooter(line)) return false;
+        float firstX = line.get(0).getX1();
+        float lastX = line.get(line.size() - 1).getX2();
+        if (policy == NativeTablePolicy.TEXT_ALIGNED_ROW_SELECTED) {
+            return firstX >= header.anchors().get(0) && firstX < header.anchors().get(header.anchors().size() - 1);
+        }
+        return lastX >= header.anchors().get(0);
+    }
+
+    private boolean looksLikeFooter(List<Word> line) {
+        String text = line.stream().map(Word::getContent).collect(Collectors.joining(" ")).toLowerCase(Locale.ROOT);
+        return text.contains("closing balance") || text.contains("end of statement") || text.startsWith("total ") || text.startsWith("page ");
+    }
+
+    private List<Float> boundaries(List<Float> anchors, float pageWidth) {
+        List<Float> result = new ArrayList<>();
+        float firstGap = anchors.size() > 1 ? anchors.get(1) - anchors.get(0) : 0.25f;
+        result.add(Math.max(0f, anchors.get(0) - firstGap / 2f));
+        for (int i = 0; i < anchors.size() - 1; i++) result.add((anchors.get(i) + anchors.get(i + 1)) / 2f);
+        float lastGap = anchors.get(anchors.size() - 1) - anchors.get(anchors.size() - 2);
+        result.add(Math.min(pageWidth, anchors.get(anchors.size() - 1) + lastGap));
+        return result;
+    }
+
+    private TableCell cell(int row, int col, float left, float right, float top, float bottom, List<Word> words) {
+        TableCell cell = new TableCell();
+        cell.setRowindex(row);
+        cell.setColindex(col);
+        cell.setRowspan(1);
+        cell.setColspan(1);
+        cell.setX1(left); cell.setY1(top); cell.setX2(right); cell.setY2(top);
+        cell.setX3(right); cell.setY3(bottom); cell.setX4(left); cell.setY4(bottom);
+        cell.setWords(words);
+        return cell;
+    }
+
+    private float centerX(Word word) {
+        return (word.getX1() + word.getX2()) / 2f;
+    }
+
+    private record Anchor(String type, float x) {}
+    private record Header(List<Word> words, List<Float> anchors) {}
+    private record PageLines(Page page, List<List<Word>> lines) {}
+
+    private static class PositionStripper extends PDFTextStripper {
+        private final int pageNumber;
+        private final List<TextPosition> positions = new ArrayList<>();
+
+        PositionStripper(int pageNumber) throws IOException {
+            this.pageNumber = pageNumber;
+            setSortByPosition(true);
+        }
+
+        @Override
+        protected void writeString(String text, List<TextPosition> textPositions) {
+            positions.addAll(textPositions);
+        }
+
+        List<Word> toWords() {
+            List<Word> words = new ArrayList<>();
+            StringBuilder text = new StringBuilder();
+            List<TextPosition> current = new ArrayList<>();
+            TextPosition previous = null;
+            for (TextPosition position : positions) {
+                String unicode = position.getUnicode();
+                boolean newLine = previous != null && Math.abs(previous.getYDirAdj() - position.getYDirAdj()) > Math.max(2f, position.getHeightDir() * 0.45f);
+                float gap = previous == null ? 0f : position.getXDirAdj() - (previous.getXDirAdj() + previous.getWidthDirAdj());
+                boolean separator = unicode == null || unicode.isBlank() || newLine || gap > Math.max(1.5f, position.getWidthOfSpace() * 0.35f);
+                if (separator && !current.isEmpty()) {
+                    words.add(word(text.toString(), current, pageNumber));
+                    text.setLength(0);
+                    current.clear();
+                }
+                if (unicode != null && !unicode.isBlank()) {
+                    text.append(unicode);
+                    current.add(position);
+                }
+                previous = position;
+            }
+            if (!current.isEmpty()) words.add(word(text.toString(), current, pageNumber));
+            return words;
+        }
+
+        private static Word word(String text, List<TextPosition> positions, int pageNumber) {
+            float left = positions.stream().map(TextPosition::getXDirAdj).min(Float::compareTo).orElse(0f) / POINTS_PER_INCH;
+            float right = positions.stream().map(position -> position.getXDirAdj() + position.getWidthDirAdj()).max(Float::compareTo).orElse(0f) / POINTS_PER_INCH;
+            float top = positions.stream().map(TextPosition::getYDirAdj).min(Float::compareTo).orElse(0f) / POINTS_PER_INCH;
+            float bottom = positions.stream().map(position -> position.getYDirAdj() + position.getHeightDir()).max(Float::compareTo).orElse(0f) / POINTS_PER_INCH;
+            Word word = new Word();
+            word.setContent(text);
+            word.setPageNumber(pageNumber);
+            word.setX1(left); word.setY1(top); word.setX2(right); word.setY2(top);
+            word.setX3(right); word.setY3(bottom); word.setX4(left); word.setY4(bottom);
+            word.setWidth(right - left); word.setHeight(bottom - top);
+            return word;
+        }
+    }
+}
